const history=[['y1949','1949 · 新校牌','把新的名字，挂在门前','试着挂上校牌，留住一次重新出发。','../assets/scene-covers/y1949.webp','plant'],['y1902','1902 · 一间教室','从一页讲义开始','走进教室，做一次关于学习的选择。','../assets/scene-covers/y1902.webp','bell'],['y1971','1971 · 灯下点校','字里行间，一盏灯','翻开书稿，看看一段文字如何被留下。','../assets/scene-covers/y1971.webp','frame'],['y2002','2002 · 百年校庆','站在同一片阳光里','试一次取景，把眼前的相聚记下来。','../assets/scene-covers/y2002.webp','camera'],['y1919','1919 · 青年之声','把一页传单，递向明天','体验一段关于选择与担当的情境。','../assets/scene-covers/y1919.webp','window'],['y1938','1938 · 迁徙课堂','书还在，课堂就在','在临时课堂中尝试一次行动。','../assets/scene-covers/y1938.webp','paper'],['y1952','1952 · 书与归途','把书送到新的书架','搬运、整理，留下重新相聚的一刻。','../assets/scene-covers/y1952.webp','bookshelf'],['y1991','1991 · 励耘','把一笔心意交给后来的人','走近书画义卖与育人记忆。','../assets/scene-covers/y1991.webp','rug'],['y1996','1996 · 校训','一笔落下，一生践行','在情境中体验校训书写。','../assets/scene-covers/y1996.webp','plaque'],['y2026','2026 · 校史馆','让木铎，再响一次','回到档案室，翻开你的校园记忆。','../assets/scene-covers/y2026.webp','bell']];
let stories=[{id:'night',title:'教室的灯还亮着',tag:'课堂 · 夜读',image:'../assets/scene-covers/y1971.webp',reward:'frame',lines:['那天自习结束得很晚。走廊已经安静下来，窗边还留着最后一盏灯。','你把散开的书页理好，听见隔壁有人轻轻关上门。桌面上的光，还够照亮一句话。','后来想起校园时，记得的不只是哪一门课，还有那盏陪你多坐了一会儿的灯。'],choices:['再读一页','把书轻轻合上']},{id:'track',title:'散场后的操场',tag:'操场 · 相遇',image:'../assets/scene-covers/y2002.webp',reward:'camera',lines:['活动散场后，操场上的声音渐渐远了。你和朋友还站在原地，谁也没急着说再见。','夕阳把影子拉得很长。有人举起相机，又笑着说，不用站得那么整齐。','照片未必记得所有细节，但那天一起走回去的路，留在了你的记忆里。'],choices:['把这一刻拍下来','陪朋友再走一圈']},{id:'window',title:'窗边的一点绿',tag:'日常 · 校园',image:'../assets/scene-covers/y1902.webp',reward:'plant',lines:['你总喜欢坐在同一扇窗边。窗外的一点绿，从学期开始陪到了学期末。','这次，你停下翻页，看见风把叶子吹向另一边。原来熟悉的地方，也一直在变化。','你决定给今天留一句话：愿以后也能发现，这些很小、却值得记住的时刻。'],choices:['看一会儿窗外','写下一句话']}];
