const method=[['记忆锚点','哪件小物、哪一束光，让你一下想起那一天？'],['人物处境','那时的你在做什么，又在期待什么？'],['玩家动作','让后来的人亲手做哪一个动作，能靠近这段记忆？'],['世界反馈','做完以后，场景里会发生什么变化？'],['余留物','故事结束后，希望留下一件什么小东西？'],['可信边界','哪些是真实发生，哪些是为体验作的概括或创作？']];
$('methodQuestions').innerHTML=method.map((x,i)=>`<article><h3>0${i+1}　${x[0]}</h3><p>${x[1]}</p></article>`).join('');
const routeNames={history:'校史回忆',community:'我们的 BNU',home:'我的家园',settings:'设置与帮助',welcome:'第一次来',method:'记忆可玩方法',feedback:'我要反馈',draft:'留下我的故事',story:'一页校园记忆',player:'走进校史',campus:'校园记忆地图',sources:'校史资料与审校',historyArchive:'二十七张档案卡',finale27:'校史馆终章'};
let currentRoute=state.page,routeStack=[];
function go(page,push=true){
 if(!routeNames[page])page='history';
 if(push&&page!==currentRoute)routeStack.push(currentRoute);
 currentRoute=page;
 document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==page);
 document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));
 $('settingsOpen').classList.toggle('active',['settings','welcome','method','feedback'].includes(page));
 $('routeBar').hidden=['history','community','home'].includes(page);$('routeTitle').textContent=routeNames[page];
 if(['history','community','home'].includes(page)){state.page=page;save()}
 renderCollections();syncPlayerPause();window.scrollTo(0,0);
 if(location.hash!=='#/'+page)window.history.pushState({route:page},'', '#/'+page);
 if(page==='home')startRoomLoop();else stopRoomLoop();if(page!=='story')stopStoryMotion();else if($('storyScene'))startStoryMotion();if(page==='community'&&window.MuduoCloud?.ready)loadSubmissions();
}
function back(){go(routeStack.pop()||state.page,false)}
$('routeBack').onclick=back;document.querySelector('.brand').onclick=e=>{e.preventDefault();go('history')};
window.addEventListener('popstate',()=>{const target=location.hash.replace('#/','');go(target==='player'&&!playing?'history':target,false)});
function open(id){if(id==='guide'){if(!$('guide').open)$('guide').showModal()}else go(id);syncPlayerPause()}
function close(id){if(id==='guide'){$('guide').close();dismissGuide()}else{if(id==='player'){$('gameFrame').src='about:blank';playing=null}back()}syncPlayerPause()}
function dismissGuide(){guideSeen=true;try{localStorage.setItem(GUIDE,'yes')}catch{persistent=false;toast('引导本次已关闭；浏览器限制保存，下次可能再次出现。')}}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();close(d.id)});d.addEventListener('close',()=>{if(d.id==='guide')dismissGuide();syncPlayerPause()})});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
$('settingsOpen').onclick=()=>open('settings');$('playerSettings').onclick=()=>open('settings');
$('guideAgain').onclick=()=>open('welcome');$('methodOpen').onclick=()=>open('method');$('feedbackOpen').onclick=()=>open('feedback');
$('guideStart').onclick=()=>{close('guide');go('history');launchHistory('y1949')};$('guideExplore').onclick=()=>close('guide');$('draftOpen').onclick=()=>open('draft');
function applySettings(){for(const name of ['music','sfx']){$(name).value=state.settings[name];$(name+'Value').textContent=state.settings[name]+'%'}$('muted').checked=state.settings.muted;$('reduceMotion').checked=state.settings.reduce;$('largeText').checked=state.settings.large;$('highContrast').checked=state.settings.contrast;$('powerSave').checked=state.settings.powerSave;document.body.classList.toggle('reduced',state.settings.reduce);document.body.classList.toggle('large',state.settings.large);document.body.classList.toggle('high-contrast',state.settings.contrast);state.settings.reduce=state.settings.reduce===true;const audioSettings={...state.settings,reduce:state.settings.reduce||state.settings.powerSave};const control=$('gameFrame').contentWindow?.__demoControl;if(control)control.settings(audioSettings);save()}
for(const name of ['music','sfx'])$(name).oninput=()=>{state.settings[name]=Number($(name).value);applySettings()};
for(const [id,key]of [['muted','muted'],['reduceMotion','reduce'],['largeText','large']])$(id).onchange=()=>{state.settings[key]=$(id).checked;applySettings()};
let audio;function bell(){if(state.settings.muted||!state.settings.sfx)return;try{audio||=new AudioContext();audio.resume();[220,330,440,660].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.05/(i+1)*state.settings.sfx/100,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+1.5);o.start();o.stop(audio.currentTime+1.6)})}catch{toast('这个浏览器暂时不能播放声音')}}$('trySound').onclick=bell;
function download(value,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('exportData').onclick=()=>download({type:'muduo-v2-demo-backup',savedAt:new Date().toISOString(),guideSeen,state},'木铎声里-Demo本机备份.json');$('importData').onclick=()=>$('importFile').click();
$('importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('备份应小于1MB');const value=JSON.parse(await file.text());if(value.type!=='muduo-v2-demo-backup')throw Error('这不是Demo备份');const replay=planBackupHistory(value.state?.historyProgress);const imported=validate(value.state);validateLayout(imported.layout,imported.unlocks);if(cloud.recovering)throw Error('正在切换档案，请稍候再导入备份');state=imported;cloud.restoreHistoryBackup(replay);preview=structuredClone(state.layout);if(value.guideSeen)dismissGuide();for(const item of state.layout){if(!validPlacement(item,state.layout)){let done=false;for(let y=0;y<6&&!done;y++)for(let x=0;x<12&&!done;x++){const proposal={...item,x,y};if(validPlacement(proposal,state.layout)){item.x=x;item.y=y;done=true}}}}preview=structuredClone(state.layout);
applySettings();const requested=location.hash.replace('#/','');go(routeNames[requested]&&!['player','story'].includes(requested)?requested:state.page,false);renderHistory27();toast('已恢复本机备份；明确完成的章节将在联网后逐项同步。')}catch(e){toast(e.message)}e.target.value=''};
let draftLocation=null;
function normalizeLocation(x){return x&&['haidian','changping','zhuhai','furen'].includes(x.campusId)?{campusId:x.campusId,placeId:typeof x.placeId==='string'?x.placeId.slice(0,60):null,displayName:String(x.displayName||'').slice(0,100)}:null}
$('campusAtlasOpen').onclick=()=>open('campus');$('draftLocationPicker').addEventListener('location-change',e=>{draftLocation=normalizeLocation(e.detail);$('draftLocationLabel').textContent=draftLocation?.displayName||'未选择定位'});$('campusBrowser').addEventListener('write-here',e=>{draftLocation=normalizeLocation(e.detail);$('draftLocationLabel').textContent=draftLocation?.displayName||'未选择定位';open('draft')});
function complete(id,title,kind,reward){if(!state.memories.some(x=>x.id===id))state.memories.push({id,title,kind,date:new Date().toISOString()});state.memories=state.memories.slice(-1000);if(!state.unlocks.includes(reward))state.unlocks.push(reward);save();renderCollections();window.MuduoCloud?.complete({eventId:crypto.randomUUID(),storyId:id,title,kind,reward});toast('这段记忆已放进家园，纪念物正在同步。')}
let chapter=0,activeStory=null;
function launchStory(id){activeStory=stories.find(x=>x.id===id);if(!activeStory){toast('这段故事暂未公开或已下架。');return}chapter=0;renderStory();open('story')}
function renderStory(){const s=activeStory;const label=s.isDemo?'虚构体验样例':s.previewOnly?'仅你可见的改编预览':'匿名校园记忆';$('storyBody').innerHTML=`<div class="eyebrow">${label} · ${chapter+1}/3</div><h2>${esc(s.title)}</h2><canvas id="storyScene" class="story-visual" width="780" height="340" tabindex="0" aria-label="可点击和方向键移动的像素记忆场景"></canvas><p class="quiet-note">模板互动场景 · 场景与对白经过叙事编排，地点不作实景复原。</p><p>${esc(s.lines[chapter])}</p><div class="story-choice">${chapter===0?s.choices.map(x=>`<button data-next="1" class="secondary">${esc(x)}</button>`).join(''):chapter===1?'<button data-next="2" class="primary">把这一刻记下来 →</button>':`<button id="collectStory" class="primary">${s.previewOnly?'返回我的投稿':'收进我的家园 →'}</button>`}</div>`;$('storyBody').querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{chapter=Number(b.dataset.next);renderStory()});if($('collectStory'))$('collectStory').onclick=()=>{if(!s.previewOnly)complete('community:'+s.id,s.title,'community',s.reward);close('story');go(s.previewOnly?'community':'home')};startStoryMotion()}
let playing=null;
function launchHistory(id){playing=history.find(x=>x[0]===id);if(!playing){toast('这个年代仍在整理中。');return}$('playerTitle').textContent=playing[1];$('playerStatus').textContent=id==='y2026'?'此刻的记忆节点：敲响木铎，为自己的来访留一页。':'完成一次操作，留下本次记忆。';let finaleButton=$('playerFinale');if(!finaleButton){finaleButton=document.createElement('button');finaleButton.id='playerFinale';finaleButton.className='primary';finaleButton.textContent='敲响木铎，留下此刻';finaleButton.onclick=()=>{if(playing?.[0]!=='y2026')return;bell();complete('history:y2026','走进校史馆','history','bell');$('playerStatus').textContent='这一刻已留在家园，可以回到记忆书架。'};$('playerSettings').before(finaleButton)}finaleButton.hidden=id!=='y2026';$('gameFrame').src='player.html?free=1&scene='+id;open('player')}
$('gameFrame').onload=()=>{try{$('gameFrame').contentWindow.__demoControl?.settings({...state.settings,reduce:state.settings.reduce||state.settings.powerSave});syncPlayerPause()}catch{}};
function syncPlayerPause(){try{$('gameFrame').contentWindow.__demoControl?.pause(currentRoute!=='player'||$('guide').open)}catch{}}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('gameFrame').contentWindow)return;if(e.data?.type==='muduo-demo-open'&&['feedback','method'].includes(e.data.panel)){open(e.data.panel);return}if(e.data?.type!=='muduo-demo-event'||!playing)return;if(e.data.event==='card_action'){const id=e.data.details?.card_id||'';if(id.startsWith(playing[0]+':')){complete('history:'+playing[0],playing[2],'history',playing[5]);$('playerStatus').textContent='本次记忆已保存，可返回家园查看。'}}});
document.addEventListener('click',e=>{const h=e.target.closest('[data-history]');if(h)launchHistory(h.dataset.history);const s=e.target.closest('[data-story]');if(s)launchStory(s.dataset.story)});
const furniture={desk:{name:'书桌',prop:'desk',w:3,scale:1.02},chair:{name:'椅子',prop:'chair',w:1,scale:.82},bookshelf:{name:'记忆书架',prop:'bookshelf',w:3,scale:1.02},lamp:{name:'台灯',prop:'lamp',w:1,scale:.90},plant:{name:'一盆校园的绿',prop:'plant',w:1,scale:.7},bell:{name:'木铎纪念物',prop:'bell',w:1,scale:.65},frame:{name:'灯下的相框',prop:'frame',w:1,scale:.65},camera:{name:'相聚的相机',prop:'camera',w:1,scale:.65},rug:{name:'回忆地毯',prop:'rug',w:2,scale:.65},window:{name:'一扇晴窗',prop:'window',w:2,scale:.65},paper:{name:'校样纸稿',prop:'paper',w:1,scale:.4},plaque:{name:'纪念墙牌',prop:'label',w:2,scale:.70}};
let preview=structuredClone(state.layout),editing=false,selected=null,drag=null,ghost=null,hits=[],undo=[];
const canvas=$('room'),ctx=canvas.getContext('2d'),props=new Image(),tiles=new Image();props.src='../assets/props-chibi-v4.png';tiles.src='../assets/tileset-cozy-v4.png';const person=new Image();person.src='../assets/characters-chibi-v6.png';props.onload=()=>{thumbCache.clear();renderCollections()};
function validPlacement(item,layout){const f=furniture[item.id];return f&&item.x>=0&&item.y>=0&&item.x+f.w<=12&&item.y<6&&!layout.some(o=>o.id!==item.id&&o.y===item.y&&o.x<item.x+f.w&&o.x+furniture[o.id].w>item.x)}
function validateLayout(layout,unlocks){if(layout.some(o=>!unlocks.includes(o.id)||!validPlacement(o,layout)))throw Error('家具位置越界或重叠')}
function renderCollections(){if(!furniture)return;$('homeCount').textContent=`已留下 ${state.memories.length} 段记忆`;if(!editing)preview=structuredClone(state.layout);$('inventory').innerHTML=Object.entries(furniture).map(([id,f])=>state.unlocks.includes(id)?`<button data-furniture="${id}" class="${selected===id?'selected':''}"><img alt="" src="${thumbnail(f.prop)}"><span>${f.name}<small>${preview.some(o=>o.id===id)?'已摆放':'已解锁，可摆放'} · ${f.w}格</small></span></button>`:`<div class="locked">${f.name} · 游玩故事后解锁</div>`).join('');$('inventory').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(!editing)startArrange();selected=b.dataset.furniture;renderCollections();$('roomHint').textContent='已选择'+furniture[selected].name+'，点选一块空地放置。'});$('memoryShelf').innerHTML=state.memories.length?state.memories.map(m=>`<article class="card"><div class="card-body"><span class="meta">${m.kind==='history'?'校史回忆':'我们的 BNU'}</span><h3>${esc(m.title)}</h3><p>这段记忆已经留在你的小屋里。</p></div><button ${m.unavailable?'disabled':''} ${m.kind==='history'?`data-history="${esc(m.id.split(':')[1])}"`:`data-story="${esc(m.id.split(':')[1])}"`}>再走进一次 →</button></article>`).join(''):'<p class="quiet-note">书架还空着。体验一段故事，第一枚记忆就会来到这里。</p>';$('draftList').innerHTML=state.drafts.length?'<h3>本机草稿</h3>'+state.drafts.map(d=>`<p>${esc(d.title)} ${d.location?' · '+esc(d.location.displayName):' · 未定位'} <small>· 仅本机保存，未上传</small></p>`).join(''):''}
function startArrange(){undo=[];editing=true;preview=structuredClone(state.layout);$('arrangeButton').hidden=true;$('saveRoom').hidden=false;$('cancelRoom').hidden=false;$('undoRoom').hidden=false;$('removeFurniture').hidden=false;$('roomHint').textContent='点选家具再点空地，或拖动家具。完成后记得保存。'}
function stopArrange(){editing=false;selected=null;ghost=null;drag=null;$('arrangeButton').hidden=false;$('saveRoom').hidden=true;$('cancelRoom').hidden=true;$('undoRoom').hidden=true;$('removeFurniture').hidden=true;$('roomHint').textContent='点击台灯开关灯，点击书架查看记忆。';renderCollections()}
$('arrangeButton').onclick=startArrange;$('saveRoom').onclick=()=>{state.layout=structuredClone(preview);save();stopArrange();toast('房间布置已保存')};$('cancelRoom').onclick=()=>{preview=structuredClone(state.layout);stopArrange()};
function coords(e){const box=canvas.getBoundingClientRect();return{x:(e.clientX-box.left)*780/box.width,y:(e.clientY-box.top)*500/box.height}}
function hit(p){return[...hits].reverse().find(h=>p.x>=h.x&&p.x<=h.x+h.w&&p.y>=h.y&&p.y<=h.y+h.h)}
function place(p){if(!selected)return;const item={id:selected,x:Math.floor((p.x-110)/42),y:Math.floor((p.y-185)/28)};if(!validPlacement(item,preview)){toast('这块位置放不下，换一块空地试试。');return}undo.push(structuredClone(preview));preview=preview.filter(x=>x.id!==selected);preview.push(item);ghost=null;renderCollections()}
canvas.onpointerdown=e=>{const p=coords(e),h=hit(p);if(editing){if(h){selected=h.id;drag={start:p};canvas.setPointerCapture(e.pointerId)}else place(p);renderCollections()}else if(h){if(h.id==='lamp'){state.lampOn=!state.lampOn;save();toast(state.lampOn?'台灯亮了。':'台灯关上了。')}else if(h.id==='bell')bell();else if(h.id==='bookshelf')$('memoryShelf').scrollIntoView({behavior:state.settings.reduce?'instant':'smooth',block:'center'});else toast(furniture[h.id].name+'，留给下一段值得记住的故事。')}};
