let applyingCloud=false,serverSubmissions=[],pendingFiles=[],draftRequestId=crypto.randomUUID();
const cloud=window.MuduoCloud;
function setSyncStatus(kind,message){$('saveStatus').textContent=message;$('cloudStatus').textContent=message;$('cloudStatus').dataset.kind=kind;$('syncRetry').hidden=!['offline','error'].includes(kind);$('cloudConflict').hidden=kind!=='conflict';$('newRecovery').hidden=!cloud?.recoveryKey;if(cloud?.recoveryKey)$('recoveryKey').value=cloud.recoveryKey}
window.addEventListener('muduo-cloud-status',e=>setSyncStatus(e.detail.kind,e.detail.message));
function receiveCloud(value,options={}){if(!value)return;try{const incoming=validate(value);applyingCloud=true;if(['completion','history'].includes(options.reason)){const pending=new Set(cloud.pendingStoryIds);state.memories=[...incoming.memories,...state.memories.filter(m=>pending.has(m.id)&&!incoming.memories.some(n=>n.id===m.id))].slice(-1000);state.unlocks=[...new Set([...state.unlocks,...incoming.unlocks])];state.historyProgress=normalizeHistoryProgress(incoming.historyProgress);for(const event of cloud.pendingHistoryEvents)state.historyProgress=applyHistoryEvent(state.historyProgress,event)}else{try{localStorage.setItem(KEY+'-before-cloud',JSON.stringify(state))}catch{}incoming.drafts=state.drafts;incoming.feedback=state.feedback;state=incoming;preview=structuredClone(state.layout);editing=false}applySettings();renderCollections();renderHistory27();save()}catch(e){toast('云端档案格式暂不兼容，本机副本已保留。')}finally{applyingCloud=false}}
$('syncRetry').onclick=async()=>{try{await cloud.retry(state);await loadPublicStories();await loadSubmissions()}catch(e){toast(e.message)}};
$('useCloud').onclick=()=>cloud.resolve('remote',state).catch(e=>toast(e.message));$('keepLocal').onclick=()=>cloud.resolve('local',state).catch(e=>toast(e.message));
$('downloadConflict').onclick=()=>{try{const value=cloud.conflict?.local||JSON.parse(localStorage.getItem(KEY+'-before-cloud')||'null');download(value||state,'木铎声里-本机冲突副本.json')}catch{download(state,'木铎声里-本机冲突副本.json')}};
$('showRecovery').onclick=()=>{$('recoveryKey').type=$('recoveryKey').type==='password'?'text':'password'};
$('downloadRecovery').onclick=()=>{if(cloud.recoveryKey)download({type:'muduo-recovery-key',recoveryKey:cloud.recoveryKey},'木铎声里-匿名档案恢复密钥.json')};
$('recoverForm').onsubmit=async e=>{e.preventDefault();const key=$('recoverInput').value.trim();if(!key)return;try{await cloud.recover(key);$('recoverInput').value='';await loadSubmissions();toast('云端档案已恢复')}catch(e){toast(e.message)}};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('当前浏览器不支持全屏')}catch{toast('当前浏览器没有允许全屏')}};
for(const [id,key] of [['highContrast','contrast'],['powerSave','powerSave']])$(id).onchange=()=>{state.settings[key]=$(id).checked;applySettings()};
function safeImage(value,fallback='../assets/scene-covers/y2026.webp'){if(typeof value!=='string'||!value.trim())return fallback;try{const url=new URL(value,location.href);return url.origin===location.origin?url.href:fallback}catch{return fallback}}
function normalizeStory(s){return{id:String(s.id).replace(/^community:/,''),title:String(s.title||'一段校园记忆').slice(0,100),tag:String(s.tag||'校园记忆').slice(0,80),image:safeImage(s.image),reward:['desk','chair','bookshelf','lamp','plant','bell','frame','camera','rug','window','paper','plaque'].includes(s.reward)?s.reward:'frame',lines:Array.isArray(s.lines)?s.lines.slice(0,3).map(x=>String(x).slice(0,4000)):[],choices:Array.isArray(s.choices)?s.choices.slice(0,2).map(x=>String(x).slice(0,120)):['再看一眼','记住这一刻'],isDemo:s.isDemo===true,location:normalizeLocation(s.location),version:s.version||1,method:s.method}}
function renderPublicStories(){const visible=stories.filter(s=>s.isDemo!==true&&!s.previewOnly),samples=stories.filter(s=>s.isDemo===true);$('communityCards').innerHTML=visible.length?visible.map(storyCard).join(''):'<p class="quiet-note empty-state">第一批故事正在等待讲述和确认。你可以留下自己的校园记忆，审核与预览确认后才会公开。</p>';$('sampleCards').innerHTML=samples.map(storyCard).join('')}
function storyCard(s){return `<article class="card"><img loading="lazy" src="${esc(s.image)}" alt="${esc(s.title)}像素场景"><div class="card-body"><span class="meta">${esc(s.tag)} · ${s.isDemo?'虚构体验样例':'匿名讲述'}</span><h3>${esc(s.title)}</h3><p>${esc(s.lines[0]||'走进这段校园记忆。')}</p>${s.location?`<small>${esc(s.location.displayName)}</small>`:''}</div><button data-story="${esc(s.id)}">走进这页记忆 →</button></article>`}
async function loadPublicStories(){try{const value=await cloud.stories();const published=(value.stories||[]).filter(s=>s.kind!=='history').map(normalizeStory).filter(s=>s.lines.length===3);const localSamples=stories.filter(s=>s.isDemo===true);stories=[...published,...localSamples.filter(s=>!published.some(p=>p.id===s.id))];renderPublicStories()}catch{renderPublicStories()}}
const statusNames={submitted:'已提交，等待初审',reviewing:'正在核对',needs_changes:'请补充材料',preview:'像素预览待确认',published:'已公开',rejected:'暂未采用',withdrawn:'已撤回',retryable_failed:'制作待重试'};
function renderSubmissions(){const box=$('mySubmissions');box.replaceChildren();const title=document.createElement('h3');title.textContent='我的投稿回执';box.append(title);if(!serverSubmissions.length){const p=document.createElement('p');p.className='quiet-note';p.textContent=cloud.ready?'还没有投稿。匿名展示前会经过编辑审核和你的预览确认。':'连接服务后可查看投稿进度。';box.append(p);return}for(const s of serverSubmissions){const card=document.createElement('article');card.className='submission-card';const h=document.createElement('h4');h.textContent=s.title;const status=document.createElement('p');status.textContent=(statusNames[s.status]||s.status)+(s.ownerConfirmed?' · 你已确认预览':'');const receipt=document.createElement('small');receipt.textContent='回执 '+s.id;card.append(h,status,receipt);if(s.preview){const button=document.createElement('button');button.textContent='查看互动预览';button.onclick=()=>previewSubmission(s);card.append(button)}if(s.status==='preview'&&!s.ownerConfirmed){const b=document.createElement('button');b.className='primary';b.textContent='我确认这份改编';b.onclick=()=>submissionAction(s.id,'confirm');card.append(b)}if(!['withdrawn','rejected'].includes(s.status)){const b=document.createElement('button');b.textContent='撤回投稿';b.onclick=()=>{if(confirm('撤回后其他人将无法再体验这段故事，确定撤回吗？'))submissionAction(s.id,'withdraw')};card.append(b)}box.append(card)}}
async function loadSubmissions(){try{const value=await cloud.submissions();serverSubmissions=value.submissions||[];renderSubmissions()}catch(e){$('submissionStatus').textContent=e.message}}
async function submissionAction(id,action){try{await cloud.action(id,action);await loadSubmissions();await loadPublicStories();toast(action==='confirm'?'已确认预览，等待编辑发布。':'已撤回，公开页面将不再展示。')}catch(e){toast(e.message)}}
function previewSubmission(s){const p=normalizeStory({...s.preview,isDemo:false});p.id='preview:'+s.id;p.previewOnly=true;const index=stories.findIndex(x=>x.id===p.id);if(index>=0)stories[index]=p;else stories.push(p);launchStory(p.id)}
$('refreshSubmissions').onclick=loadSubmissions;
function imageFilesChanged(e){pendingFiles=[...e.target.files];$('imagePreviewList').replaceChildren();if(pendingFiles.length>5){pendingFiles=[];e.target.value='';toast('最多选择5张图片');return}for(const file of pendingFiles){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){pendingFiles=[];e.target.value='';$('imagePreviewList').replaceChildren();toast('图片须为10MB以内的PNG、JPEG或WebP');return}const im=document.createElement('img');const url=URL.createObjectURL(file);im.src=url;im.alt='待提交的本机图片';im.onload=()=>URL.revokeObjectURL(url);$('imagePreviewList').append(im)}}
$('draftImage').onchange=imageFilesChanged;
function saveLocalDraft(){const title=$('draftTitle').value.trim(),text=$('draftText').value.trim();if(!text){toast('草稿至少写下一点正文吧。');return}state.drafts.push({title:title||'未命名草稿',text,location:draftLocation,date:new Date().toISOString()});state.drafts=state.drafts.slice(-20);save();renderCollections();toast('文字草稿已保存，图片请在正式提交时重新选择。')}
$('saveLocalDraft').onclick=saveLocalDraft;
$('draftForm').onsubmit=async e=>{e.preventDefault();const title=$('draftTitle').value.trim(),text=$('draftText').value.trim();if(text.length<100){toast('公开投稿请至少写100字，短片段可以先保存草稿。');return}if(!$('submissionConsent').checked){toast('请确认匿名展示和互动改编许可。');return}if(!cloud.ready){toast('服务未连接，请先保存草稿，稍后再提交。');return}const button=$('submitStory');button.disabled=true;$('submissionStatus').textContent='正在提交，请稍候…';try{const mediaIds=[];for(let i=0;i<pendingFiles.length;i++){$('submissionStatus').textContent=`正在上传第${i+1}/${pendingFiles.length}张图片…`;const value=await cloud.upload(pendingFiles[i]);mediaIds.push(value.mediaId)}const result=await cloud.submit({title,text,location:draftLocation,consent:true,mediaIds,clientRequestId:draftRequestId});draftRequestId=crypto.randomUUID();$('draftForm').reset();pendingFiles=[];$('imagePreviewList').replaceChildren();draftLocation=null;$('draftLocationLabel').textContent='未选择定位';$('draftLocationPicker').clearSelection?.();$('submissionStatus').textContent='已收到，回执 '+result.submission.id;await loadSubmissions();go('community');toast('投稿已收到，审核和你的预览确认后才会公开。')}catch(e){$('submissionStatus').textContent=e.message;toast(e.message)}finally{button.disabled=false}};
$('feedbackForm').onsubmit=async e=>{e.preventDefault();const text=$('feedbackText').value.trim();if(!text)return;state.feedback.push({text,date:new Date().toISOString()});state.feedback=state.feedback.slice(-20);save();try{await cloud.feedback(text);$('feedbackForm').reset();close('feedback');toast('反馈已送达，感谢你帮助这段记忆变得更好。')}catch(e){toast('反馈已保存在本机，联网后可再次发送。')}};
async function loadHistorySources(){try{const response=await fetch('../assets/history-sources.json');if(!response.ok)return;const data=await response.json();window.__historySources=data.periods||[];const box=$('historySources');box.replaceChildren();for(const period of window.__historySources){const article=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=period.title||period.id;p.textContent=period.summary||'';article.append(h,p);const note=document.createElement('small');note.textContent=(period.dialogueLabel||'对白为情境创作')+' · '+(period.reviewStatus||'逐条审校中');article.append(note);for(const source of period.sources||[]){const link=document.createElement('a');try{const u=new URL(source.url);if(!['https:','http:'].includes(u.protocol))continue;link.href=u.href}catch{continue}link.textContent=source.title||'资料来源';link.target='_blank';link.rel='noopener';article.append(link)}box.append(article)}}catch{}}
$('historySourcesOpen').onclick=()=>open('sources');
function startRelease(){renderPublicStories();loadHistorySources();cloud.start(state,receiveCloud).then(async ok=>{if(ok){await loadPublicStories();await loadSubmissions()}})}

