 rect(0,0,780,340,night?'#334854':'#bad5c0');rect(0,65,780,130,night?'#526055':'#b7c18b');rect(0,160,780,180,night?'#a59373':'#dfc99b');for(let y=165;y<340;y+=26){rect(0,y,780,1,'#8f795740');for(let x=(y/26|0)%2?0:30;x<780;x+=60)rect(x,y,1,26,'#8f795730')}
