// Explicit 27-view history controller, inserted inside the V2 application closure.
let historyContent=null,activeHistoryChapter=null;
function historyProgressDefaults(){return{cardVersion:1,cards:[],checkpoints:{},views:Object.fromEntries(['y1902','y1919','y1938','y1949','y1952','y1971','y1991','y1996','y2002'].map(id=>[id,{unlocked:1,completed:[],active:1}]))}}
function normalizeHistoryProgress(value){const p=historyProgressDefaults(),keys={y1902:['classics','pedagogy','west'],y1919:['march','stay','letter'],y1938:['move','teach','hide'],y1949:['center','close','off'],y1952:['fuyin','beishi','common'],y1971:['check','doubt','rest'],y1991:['ask','scrolls','student'],y1996:['ink','meaning','paper'],y2002:['center','close','off']},known=new Set(Object.entries(keys).flatMap(([era,cards])=>cards.map(k=>era+':'+k)));p.cards=[...new Set((Array.isArray(value?.cards)?value.cards:[]).filter(id=>known.has(id)))];for(const [key,cp] of Object.entries(value?.checkpoints||{})){if(/^y(1902|1919|1938|1949|1952|1971|1991|1996|2002):[123]$/.test(key)&&cp&&typeof cp==='object'&&!Array.isArray(cp)&&JSON.stringify(cp).length<=8192)p.checkpoints[key]=structuredClone(cp)}for(const era of Object.keys(p.views)){const incoming=value?.views?.[era],done=[];for(let n=1;n<=3;n++){if(!incoming?.completed?.includes(n))break;done.push(n)}const unlocked=Math.min(3,done.length+1);p.views[era]={unlocked,completed:done,active:Number.isInteger(incoming?.active)&&incoming.active>=1&&incoming.active<=unlocked?incoming.active:Math.min(3,done.length+1)}}return p}
function applyHistoryEvent(progress,event){const p=normalizeHistoryProgress(progress);if(event.kind==='import'){const known=new Set(historyContent?.eras.flatMap(e=>e.cards.map(c=>c.id))||[]);p.cards=[...new Set([...p.cards,...event.cards.filter(id=>known.has(id))])];return p}const v=p.views[event.era];if(!v||event.view<1||event.view>v.unlocked)return p;const era=historyContent?.eras.find(e=>e.id===event.era),chapter=era?.views.find(v=>Number(v.variant||v.id)===event.view),known=new Set(era?.cards.map(c=>c.id)||[]);p.cards=[...new Set([...p.cards,...(event.cardIds||[]).filter(id=>known.has(id))])];v.active=event.view;if(event.checkpoint&&!v.completed.includes(event.view))p.checkpoints[event.era+':'+event.view]=structuredClone(event.checkpoint);if(event.completed===true){const needed=(chapter?.cardKeys||[]).map(k=>k.includes(':')?k:event.era+':'+k);if(needed.every(id=>p.cards.includes(id))){delete p.checkpoints[event.era+':'+event.view];if(!v.completed.includes(event.view))v.completed.push(event.view);v.completed.sort();v.unlocked=Math.min(3,v.completed.length+1);v.active=Math.min(3,event.view+1)}}return p}

function planBackupHistory(raw){if(raw===undefined)return[];if(!historyContent)throw Error('章节目录尚未加载，请稍后再导入备份');if(!raw||raw.cardVersion!==1||!Array.isArray(raw.cards)||raw.cards.length>27||!raw.views||typeof raw.views!=='object')throw Error('备份章节进度格式不正确');const known=new Set(historyContent.eras.flatMap(e=>e.cards.map(c=>c.id))),cards=[...new Set(raw.cards)];if(cards.some(id=>!known.has(id)))throw Error('备份包含未知档案卡');for(const key of Object.keys(raw.views))if(!historyContent.eras.some(e=>e.id===key))throw Error('备份包含未知年代');const events=[{kind:'import',eventId:crypto.randomUUID(),cards}];function checkJSON(v,depth=0){if(depth>5)throw Error('章节检查点层级过深');if(v===null||typeof v==='boolean')return;if(typeof v==='number'){if(!Number.isFinite(v)||Math.abs(v)>Number.MAX_SAFE_INTEGER)throw Error('章节检查点数值不正确');return}if(typeof v==='string'){if(v.length>300)throw Error('章节检查点文字过长');return}if(typeof v!=='object')throw Error('章节检查点格式不正确');const entries=Object.values(v);if(entries.length>64)throw Error('章节检查点内容过多');for(const item of entries)checkJSON(item,depth+1)}for(const era of historyContent.eras){const value=raw.views[era.id]||{completed:[],unlocked:1,active:1};if(!Array.isArray(value.completed)||value.completed.length>3||value.completed.some((n,i)=>n!==i+1))throw Error('备份视角完成顺序不正确');const unlocked=Math.min(3,value.completed.length+1);if(value.unlocked!==unlocked||!Number.isInteger(value.active)||value.active<1||value.active>unlocked)throw Error('备份视角解锁状态不正确');for(const view of value.completed){const chapter=era.views.find(v=>Number(v.variant||v.id)===view),needed=chapter.cardKeys.map(k=>k.includes(':')?k:era.id+':'+k);if(!needed.every(id=>cards.includes(id)))throw Error('备份声明完成的视角缺少对应档案卡');events.push({eventId:crypto.randomUUID(),era:era.id,view,cardIds:needed,completed:true})}const key=era.id+':'+value.active,cp=raw.checkpoints?.[key];if(cp!==undefined){if(value.completed.includes(value.active)||!cp||typeof cp!=='object'||Array.isArray(cp)||new TextEncoder().encode(JSON.stringify(cp)).length>8192)throw Error('备份活动检查点不正确');checkJSON(cp);events.push({eventId:crypto.randomUUID(),era:era.id,view:value.active,cardIds:[],completed:false,checkpoint:cp})}}for(const key of Object.keys(raw.checkpoints||{}))if(!historyContent.eras.some(e=>key===e.id+':'+raw.views[e.id]?.active))throw Error('备份包含未知或非活动章节检查点');return events}
function historyStats(){const p=normalizeHistoryProgress(state.historyProgress);return{cards:p.cards.length,views:Object.values(p.views).reduce((n,v)=>n+v.completed.length,0)}}
function renderHistory27(){if(!historyContent)return;state.historyProgress=normalizeHistoryProgress(state.historyProgress);const p=state.historyProgress,counts=historyStats();$('historyProgressSummary').textContent=`档案卡 ${counts.cards}/27　·　访问视角 ${counts.views}/27`;$('historyCards').innerHTML=historyContent.eras.map(era=>{const progress=p.views[era.id],active=progress.active;return `<article class="card history-era"><img loading="lazy" src="../assets/history-views/${esc(era.id)}-${active}.webp" alt="${esc(era.title)}第${active}视角的实际像素场景"><div class="card-body"><span class="meta">${esc(era.title)} · ${progress.completed.length}/3 视角</span><h3>${esc(era.views.find(v=>Number(v.variant||v.id)===active)?.title||era.title)}</h3><p>档案卡 ${era.cards.filter(c=>p.cards.includes(c.id)).length}/3 · 三个视角各有实际目标</p></div><div class="chapter-buttons">${era.views.map(v=>{const n=Number(v.variant||v.id),done=progress.completed.includes(n),locked=n>progress.unlocked;return `<button data-history-era="${esc(era.id)}" data-history-view="${n}" ${locked?'disabled':''}><span>${done?'✓':locked?'🔒':'→'} 视角 ${n}</span><b>${esc(v.title)}</b><small>${done?'已完成，可重玩':locked?'先完成前一视角':'已解锁，进入本章'}</small></button>`}).join('')}</div></article>`}).join('');$('finale27Status').textContent=counts.cards===27&&counts.views===27?'27张卡与27个视角均已完成。走进校史馆，把这段记忆交给下一个人。':`终章将在两套进度都完成后开启。还差 ${27-counts.cards} 张卡、${27-counts.views} 个视角。`;$('finale27Open').disabled=counts.cards!==27||counts.views!==27;renderHistoryArchive()}
function renderHistoryArchive(){if(!historyContent)return;const p=state.historyProgress;$('historyArchiveList').innerHTML=historyContent.eras.map(era=>`<section class="archive-era"><h2>${esc(era.title)}</h2><div class="cards">${era.cards.map(c=>{const owned=p.cards.includes(c.id);return `<article class="card ${owned?'':'card-uncollected'}"><div class="card-body"><span class="meta">${owned?'已收集':'尚未收集'} · ${esc(c.id)}</span><h3>${esc(c.title)}</h3><p>${owned?esc(c.text||'这张档案卡已经留在你的记忆里。'):'完成对应章节目标后，再翻开这一页。'}</p>${owned?'<small>'+esc(c.dialogueLabel||'情境创作，非史料原话')+'</small>':''}</div></article>`}).join('')}</div></section>`).join('')}
const legacyLaunchHistory=launchHistory;
launchHistory=function(id,requestedView){if(id==='y2026'){go('finale27');renderHistory27();return}if(!historyContent){toast('章节目录正在加载，请稍后再试。');return}const era=historyContent.eras.find(e=>e.id===id);if(!era){toast('这个年代暂未整理。');return}const progress=state.historyProgress.views[id],view=Number(requestedView||progress.active||1);if(view>progress.unlocked||view<1||view>3){toast('先完成前一个视角，再继续向后走。');return}activeHistoryChapter={era:id,view};progress.active=view;playing=history.find(h=>h[0]===id);$('playerTitle').textContent=era.title+' · 视角 '+view+'/3';$('playerStatus').textContent='完成本章目标后保存检查点；中途操作不算通关。';if($('playerFinale'))$('playerFinale').hidden=true;$('player').classList.add('history27-player');$('gameFrame').src='player27.html?era='+id+'&view='+view;save();open('player')};
function openFinale27(){const counts=historyStats();if(counts.cards!==27||counts.views!==27){go('finale27');renderHistory27();return}activeHistoryChapter={era:'y2026',view:1};playing=history.find(h=>h[0]==='y2026');$('playerTitle').textContent='2026 · 把钟声交给下一个人';$('playerStatus').textContent='两套27进度已完成。翻开档案，敲响木铎。';if($('playerFinale'))$('playerFinale').hidden=true;$('player').classList.add('history27-player');$('gameFrame').src='player27.html?era=y2026&view=1&finale=1';open('player')}
document.addEventListener('click',e=>{const button=e.target.closest('[data-history-view]');if(button)launchHistory(button.dataset.historyEra,Number(button.dataset.historyView))});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('gameFrame').contentWindow)return;const event=e.data;if(event?.type==='muduo-history-height'){if(Number.isFinite(event.height))$('gameFrame').style.height=Math.min(4000,Math.max(480,event.height))+'px';return}if(event?.type==='muduo-history-progress'){if(!activeHistoryChapter||event.era!==activeHistoryChapter.era||event.view!==activeHistoryChapter.view)return;const era=historyContent?.eras.find(x=>x.id===event.era),chapter=era?.views.find(v=>Number(v.variant||v.id)===event.view);if(!chapter||event.view>state.historyProgress.views[event.era].unlocked||!Array.isArray(event.cardIds))return;const allowed=new Set((chapter.cardKeys||[]).map(k=>k.includes(':')?k:event.era+':'+k));if(event.cardIds.some(id=>!allowed.has(id)))return;const value={eventId:typeof event.eventId==='string'?event.eventId:crypto.randomUUID(),era:event.era,view:event.view,cardIds:event.cardIds,completed:event.completed===true,...(event.checkpoint&&JSON.stringify(event.checkpoint).length<=8192?{checkpoint:event.checkpoint}:{})};state.historyProgress=applyHistoryEvent(state.historyProgress,value);if(value.completed&&event.view===3){const h=history.find(x=>x[0]===event.era);if(!state.memories.some(m=>m.id==='history:'+event.era))state.memories.push({id:'history:'+event.era,title:h[2],kind:'history',date:new Date().toISOString()});if(!state.unlocks.includes(h[5]))state.unlocks.push(h[5])}save();renderHistory27();renderCollections();cloud.history(value,event.force===true);$('playerStatus').textContent=value.completed?'本章目标已完成，章节检查点正在保存。':'已获得一张档案卡，本章目标还在继续。'}else if(event?.type==='muduo-history-ready'){if(activeHistoryChapter?.era===event.era&&activeHistoryChapter.view===event.view)e.source.postMessage({type:'muduo-history-resume',era:event.era,view:event.view,checkpoint:state.historyProgress.checkpoints[event.era+':'+event.view]||null,completed:state.historyProgress.views[event.era]?.completed.includes(event.view)||false},location.origin)}else if(event?.type==='muduo-history-next'){launchHistory(event.era,event.view)}else if(event?.type==='muduo-history-return'){close('player');go('history')}else if(event?.type==='muduo-history-finale'){const counts=historyStats();if(counts.cards===27&&counts.views===27)complete('history:y2026','把钟声交给下一个人','history','bell')}});
$('historyArchiveOpen').onclick=()=>{renderHistoryArchive();open('historyArchive')};$('finale27Open').onclick=openFinale27;$('finale27Atlas').onclick=()=>{renderHistoryArchive();open('historyArchive')};
$('importLegacyCards').onclick=async()=>{try{const raw=JSON.parse(localStorage.getItem('muduo-v2-player-cards-v1')||'{}'),cards=Array.isArray(raw.cards)?raw.cards:[];const known=new Set(historyContent.eras.flatMap(e=>e.cards.map(c=>c.id))),real=[...new Set(cards.filter(id=>known.has(id)))];if(!real.length){toast('本机旧档案里没有可导入的真实卡片。');return}if(!confirm(`将本机旧档案中的 ${real.length} 张卡导入当前匿名档案？只导入卡片，不推断视角完成，也不会解锁家具。`))return;await cloud.importHistory(real);renderHistory27();toast('旧卡片已导入；章节视角仍需实际游玩。')}catch(e){toast(e.message)}};
